INSERT INTO `posts` (`id`, `title`, `content`, `excerpt`, `cover`, `author_id`, `category_id`, `status`, `is_top`, `top_order`, `view_count`, `like_count`, `comment_count`, `published_at`, `offlined_by`, `offlined_at`, `created_at`, `updated_at`) VALUES
(1810000000000000001, 'Spring Boot 3 接入 Redis 缓存的完整踩坑记录：注解、序列化与 TTL', '上周把 CloudLog 的文章列表缓存从手写的 RedisTemplate 切换到了 Spring Cache 抽象，原本预计半天搞定，结果断断续续折腾了两天。回头整理时发现，每个坑都不算冷门，值得按时间线记下来。\n\n![缓存监控曲线示例](http://127.0.0.1:9000/cloudlog/post/content/202610/f9f0f7f0-e081-4ab3-9d51-9022f41b097f.png)\n\n## 第一个坑：注解不生效\n\n@Cacheable 打在同一个类的内部调用方法上，AOP 代理根本没机会拦截，缓存命中率永远是零。这个问题的根源在于 Spring 的声明式缓存建立在代理之上：\n\n```java\n@Service\npublic class PostService {\n    public List<PostBrief> hotList() {\n        // 内部调用走的是 this，绕过了代理\n        return this.findHot();\n    }\n\n    @Cacheable(value = "post:hot")\n    public List<PostBrief> findHot() {\n        /* 查询与组装 */\n    }\n}\n```\n\n解法是拆类，或者注入自身代理。我选了拆类，顺带把缓存边界从 service 内部收拢到了独立的 CacheFacade。\n\n## 第二个坑：JDK 序列化体积爆炸\n\n默认的 JdkSerializationRedisSerializer 把一个 2KB 的文章摘要对象序列化成了 11KB，命中率上去了，内存和带宽却先扛不住。换成 Jackson 序列化器之后注意两点：\n\n- 给实体补默认构造器，否则反序列化直接抛异常\n- LocalDateTime 需要 JavaTimeModule，并且关闭 WRITE_DATES_AS_TIMESTAMPS\n\n![序列化体积对比](http://127.0.0.1:9000/cloudlog/post/content/202610/6b02824b-8cef-4b87-8271-3bfdf7398b35.png)\n\n## 第三个坑：统一 TTL 引发的同时失效\n\n列表、详情、热榜三类 key 原本共用 30 分钟过期，结果每次过期都伴随一小波 DB 尖峰。改成基础 TTL 加随机抖动之后，曲线立刻平了。\n\n```yaml\nspring:\n  cache:\n    redis:\n      time-to-live: 1800s\n```\n\n缓存这块没有银弹，@Cacheable 只是入口，真正决定稳定性的是 key 设计、序列化与过期策略这三件小事。后续把多级缓存接进来之后再补一篇。', '把站点缓存从自研切到 Spring Cache 的过程比想象中曲折：注解不生效、序列化体积爆炸、统一 TTL 导致同时失效，本文按时间线记录每个坑的现象、定位与最终方案。', 'http://127.0.0.1:9000/cloudlog/post/cover/202610/33c517a0-ec52-4108-9124-4786fed0df6b.webp', 1800000000000000001, 1, 'published', 0, 0, 3265, 10, 6, '2026-10-02 10:15:00', NULL, NULL, '2026-10-01 18:20:00', '2026-10-02 10:15:00'),
(1810000000000000002, 'MySQL 8 索引失效的十个真实案例，每一个都来自线上告警', '做 DBA 兼职这两年，我把处理过的慢查询工单按根因归了类，发现索引失效的场景重复率高得惊人。挑出最常见的十个案例，每个都附上当时的执行计划变化。\n\n![慢查询工单分布](http://127.0.0.1:9000/cloudlog/post/content/202610/3bf066da-b089-439e-9cb7-336bad65703a.png)\n\n## 隐式类型转换\n\n最经典的一个：phone 字段是 VARCHAR，查询条件却写成了数字字面量，索引直接失效走全表。\n\n```sql\n-- 失效：隐式转换，等价于对 phone 列做类型转换后比较\nSELECT * FROM users WHERE phone = 13800001234;\n-- 命中：保持类型一致\nSELECT * FROM users WHERE phone = CAST(13800001234 AS CHAR);\n```\n\n## 前导模糊与 OR 断链\n\n- LIKE 的通配符不能放开头，这是最容易被新人忽略的一条\n- OR 两侧只要有一列没索引，整个条件就退化为全表扫描\n- 联合索引遵循最左前缀，跳过第一列等于没有索引\n\n![执行计划对比](http://127.0.0.1:9000/cloudlog/post/content/202610/4e2cd09b-a856-4f9f-ae99-a80366f32d64.png)\n\n## 函数包裹\n\nDATE(create_time) = CURDATE() 这类写法在 8.0 之后部分场景可以走函数索引，但更稳妥的方案是改写成范围条件。\n\n```sql\nSELECT * FROM orders\nWHERE create_time >= CURDATE()\n  AND create_time < CURDATE() + INTERVAL 1 DAY;\n```\n\n索引优化没有玄学，看懂 explain 的 type、key、rows 三列，八成的失效问题都能当场定位。', '十次线上慢查询告警回溯下来，索引失效的原因翻来覆去就是那几样：隐式转换、函数包裹、前导模糊、OR 断链。本文把每个案例的 SQL、执行计划与修复方式原样贴出来。', 'http://127.0.0.1:9000/cloudlog/post/cover/202610/01f3e7cc-1017-4eac-86fa-4e605cb6c08f.webp', 1800000000000000002, 3, 'published', 0, 0, 2841, 9, 5, '2026-10-01 21:40:00', NULL, NULL, '2026-09-29 22:10:00', '2026-10-01 21:40:00'),
(1810000000000000003, 'Redis 分布式锁演进史：从 SETNX 到 Redisson 看门狗', '分布式锁大概是每个后端都要亲手踩一遍的轮子。从最早照着教程写 SETNX，到现在全量替换成 Redisson，中间的四次迭代值得复盘。\n\n## 第一版：SETNX 加过期时间\n\n```redis\nSET lock:order:1001 3f2b1c9d NX EX 30\n```\n\n问题是释放锁时没法校验持有者，A 的锁可能被 B 删掉。加一层 Lua 比对 value 才算勉强能用。\n\n![锁竞争时序](http://127.0.0.1:9000/cloudlog/post/content/202609/17fc2031-0f88-42fa-8f3d-2f22429f3793.png)\n\n## 第二版：Lua 原子释放\n\n把「比对持有者再删除」压进一个 Lua 脚本，原子性问题解决了，但业务超时导致锁提前过期的新问题又冒出来。\n\n## 第三版：看门狗续期\n\nRedisson 的 watchdog 默认每 10 秒续到 30 秒，业务线程活着锁就一直在。这一版基本覆盖了九成的场景：\n\n- 加锁解锁全部走 tryLock 的 finally 块\n- 等待时间必须小于租期，避免雪片式自旋\n- 锁粒度尽量细，按业务键而不是整个接口\n\n![看门狗续期示意](http://127.0.0.1:9000/cloudlog/post/content/202609/9fe05823-3fb7-4eec-836c-e638aaed5d2b.png)\n\n## 第四版：多节点 RedLock 的取舍\n\n主从切换瞬间锁可能丢失，RedLock 用多实例多数派解决，但运维成本也上来了。我们最终选择接受这个概率风险，用业务层的幂等兜底。锁解决的是效率问题，幂等解决的是正确性问题，别把宝全押在锁上。', '锁没释放、锁被别人删、业务没执行完锁先过期，这三个问题几乎是每套分布式锁的成长礼。本文沿着项目里锁方案的四次迭代，把选型逻辑讲清楚。', 'http://127.0.0.1:9000/cloudlog/post/cover/202609/934df48b-9a74-4163-afdb-59b1e427e8f1.webp', 1800000000000000001, 4, 'published', 0, 0, 2608, 8, 4, '2026-09-28 08:30:00', NULL, NULL, '2026-09-26 15:40:00', '2026-09-28 08:30:00'),
(1810000000000000004, 'Vue 3 组合式 API 落地一年的收益与代价', '去年这时候，我们下定决心把一个五年历史的 Vue 2 中后台项目迁到 Vue 3。现在回头看，这份成绩单里有惊喜也有教训。\n\n![迁移进度看板](http://127.0.0.1:9000/cloudlog/post/content/202607/8570b67d-ea2b-48ab-8434-996559a97dac.png)\n\n## 迁移带来的真实收益\n\n- 逻辑复用从 mixins 的命名冲突地狱解放出来，composable 的依赖关系一目了然\n- TypeScript 支持脱胎换骨，defineProps 的类型推导省掉了大量重复声明\n- 大组件拆分成本显著下降，把一段响应式逻辑抽成 use 函数只要十分钟\n\n## 交过的学费\n\n最大的坑是响应式丢失。解构 props、把 reactive 对象传给第三方库、在 setTimeout 里直接赋值，每一处都产生过难查的 bug。\n\n```js\n// 错误示范：解构即断链\nconst { list, loading } = usePostList();\n// 正确：用 toRefs 保持响应式\nconst { list, loading } = toRefs(usePostList());\n```\n\n另一个教训是迁移节奏：值钱的不是语法糖，而是把组件里的副作用收拢到组合函数里。如果只是把 options 换个写法，收益接近于零。给同样在观望的团队一个建议：新代码强制组合式，老代码按需迁移，别立全面重构的军令状。', '一个五年历史的中后台项目全面迁到组合式 API 之后，代码量降了三成，但也交了不少学费。一年后回看，有些迁移根本不值得，有些则越早做越好。', 'http://127.0.0.1:9000/cloudlog/post/cover/202607/58b523bc-897a-4832-b656-d130b92f8d51.webp', 1800000000000000003, 2, 'published', 0, 0, 5024, 3, 1, '2026-07-03 11:00:00', NULL, NULL, '2026-07-02 20:30:00', '2026-07-03 11:00:00'),
(1810000000000000005, 'Docker 镜像瘦身的六板斧：从一个 1.2GB 的后端镜像说起', '接手项目第一天拉镜像，1.2GB，内网传输时把 CI 流水线拖到十分钟起。半年后这个数字定格在 218MB，过程记下来。\n\n![镜像体积变化趋势](http://127.0.0.1:9000/cloudlog/post/content/202609/e48edca0-b7fc-4cfe-9307-9e3e9c493a8d.png)\n\n## 六步瘦身路径\n\n1. 基础镜像从 openjdk 全量版换成 eclipse-temurin 的 JRE 变体，一刀减掉四成\n2. 多阶段构建，编译产物从构建容器拷贝进运行容器，Maven 仓库不再进镜像\n3. .dockerignore 补全，target、.git、日志目录统统挡在构建上下文之外\n4. 合并 RUN 指令并清理包管理器缓存，层的数量直接影响层的体积\n5. 依赖层与代码层分离，源码变更时只重传薄薄一层\n6. jlink 裁剪出只含所需模块的运行时，这一步最有技术含量也最容易被跳过\n\n```dockerfile\nFROM eclipse-temurin:21-jre-alpine\nWORKDIR /app\nCOPY app.jar app.jar\nENTRYPOINT ["java", "-jar", "app.jar"]\n```\n\n![构建时间对比](http://127.0.0.1:9000/cloudlog/post/content/202609/f96cf5a1-b041-42d0-aeae-83758353e7ea.png)\n\n镜像小了之后，滚动更新的窗口期从分钟级降到秒级，这可能是比省磁盘更实际的收益。', '一个 Spring Boot 应用的镜像居然有 1.2GB。从换基础镜像到多阶段构建，再到层缓存与 jlink，六步做完压到了 218MB，构建时间反而更短。', 'http://127.0.0.1:9000/cloudlog/post/cover/202609/0e21d671-6110-4a54-9557-f937a56d6e03.webp', 1800000000000000002, 5, 'published', 0, 0, 1180, 4, 2, '2026-09-14 14:20:00', NULL, NULL, '2026-09-13 21:15:00', '2026-09-14 14:20:00'),
(1810000000000000006, '订单超时关闭的五种实现：延时队列、时间轮与 Redis ZSet 选型笔记', '订单三十分钟未支付自动关闭，是电商系统绕不开的需求。我们的实现前后换了三版，加上调研过的备选，一共五种路径。\n\n![方案对比总览](http://127.0.0.1:9000/cloudlog/post/content/202609/92859437-401d-4aa1-a038-fd8ae8141283.png)\n\n## 五种方案速览\n\n1. 数据库轮询：实现最简单，扫表压力随订单量线性上涨，只适合日订单三位数的阶段\n2. Redis ZSet：score 存过期时间戳，消费者轮询 zrangebyscore，实现轻量但要处理并发取出的竞争\n3. 延迟消息：RocketMQ 原生延迟等级，Kafka 需要自己按时间分 topic，可靠但灵活度受限\n4. 时间轮：Netty 的 HashedWheelTimer 单机效率极高，但进程重启后任务丢失，需要持久化兜底\n5. 状态机加对账：把超时当成一种状态迁移，用定时对账修正漏网之鱼，任何方案都需要这层保险\n\n```java\n// ZSet 取出到期订单后必须原子抢占，避免多消费者重复处理\nString script = \"\"\"\nif redis.call(\"zrem\", KEYS[1], ARGV[1]) == 1 then\n  return 1\nend\nreturn 0\n\"\"\";\n```\n\n我们的终态是 RocketMQ 延迟消息加每天一次对账，中间踩的坑主要在消息重复消费，靠订单状态机幂等消化。', '超时关单看着是个小需求，实现路径却有五条，成本和可靠性的差别比想象中大。本文按团队演进顺序讲完五种方案，附上各自的适用边界。', 'http://127.0.0.1:9000/cloudlog/post/cover/202609/25add734-e4c9-4443-8418-dba4612d2bf2.webp', 1800000000000000010, 7, 'published', 0, 0, 1350, 6, 3, '2026-09-20 09:00:00', NULL, NULL, '2026-09-18 11:05:00', '2026-09-20 09:00:00'),
(1810000000000000007, '接口幂等的七种武器：写给自己看的系统设计清单', '幂等是后端面试的高频题，更是线上事故的常客。把常用方案整理成清单，下次设计接口时按图索骥。\n\n![幂等方案全景图](http://127.0.0.1:9000/cloudlog/post/content/202604/9e2bdbe7-83a2-48e0-af18-414dc3758d7d.png)\n\n## 清单正文\n\n1. 唯一业务约束：靠数据库唯一索引兜底，最硬的一道防线，任何方案都应该有它压阵\n2. 防重 token：进入页面先领 token，提交时原子校验删除，适合表单场景\n3. 分布式锁：并发去重的万能钥匙，但锁失败后要想清楚返回什么\n4. 状态机：用条件更新天然幂等，改状态只允许带前置状态做条件\n5. 去重表：把「处理过」落库，消费端先查再处理，适合 MQ 消费场景\n6. 版本号乐观锁：适合需要保留每次修改的场景\n7. 前端防抖：只是体验优化，永远不能当幂等方案\n\n```sql\nUPDATE orders SET status = 2 WHERE id = 1001 AND status = 1;\n```\n\n清单会持续更新，下一批候选是幂等键的 HTTP 语义化用法和 TCC 的幂等坑位。', '支付回调重试、用户双击提交、MQ 重复投递，最终都指向同一个问题：接口幂等。这篇清单式笔记把七种主流方案的适用场景一次理清。', 'http://127.0.0.1:9000/cloudlog/post/cover/202604/18345acd-d542-4f72-8f96-0f7e3c5e1c92.webp', 1800000000000000001, 8, 'published', 1, 10, 640, 2, 1, '2026-04-26 09:40:00', NULL, NULL, '2026-04-25 19:30:00', '2026-04-26 09:40:00'),
(1810000000000000008, 'MyBatis-Plus 分页与深翻页优化：一次千万级列表的救火实录', '运营同学反馈导出列表翻到后面就超时，排查发现单表已经一千两百万行，limit 500000, 20 的写法要先把前 50 万行捞出来再丢弃。\n\n![慢查询执行计划](http://127.0.0.1:9000/cloudlog/post/content/202605/668e541c-ba67-49c1-b7ef-3e45e54c86ce.png)\n\n## 深翻页为什么慢\n\nlimit 的偏移量意味着数据库要扫描并丢弃 offset 之前的所有行，页码越深，浪费越大。执行计划里 type 一直是 ALL，索引形同虚设。\n\n## 游标翻页：把 offset 变成条件\n\n不让数据库数行数，而是记住上一页的最后一个 id，下一页从它之后接着取：\n\n```sql\nSELECT id, title, created_at FROM posts\nWHERE id < 1810000000000000000\nORDER BY id DESC LIMIT 20;\n```\n\n配合覆盖索引，整条查询只在索引树上滑行，回表次数几乎归零。\n\n![优化前后耗时对比](http://127.0.0.1:9000/cloudlog/post/content/202605/5158589f-2b4b-471c-8138-9c39f1dae013.png)\n\n## 兜底与产品化\n\n- 跳页需求保留，但限制最大页深并明示用户\n- 导出场景一律走异步任务，别让分页接口背锅\n- 监控上看，p95 从 4.2 秒降到 80 毫秒，夜里终于没有慢查询告警了', '运营后台翻到第五万页直接超时。limit 深翻页的本质缺陷没有银弹，但游标翻页加覆盖索引的组合，把 4.2 秒的查询压到了 80 毫秒。', 'http://127.0.0.1:9000/cloudlog/post/cover/202605/24879e15-ae7c-4777-88ba-e7c7f943dd23.webp', 1800000000000000002, 1, 'published', 1, 5, 720, 1, 1, '2026-05-18 20:30:00', NULL, NULL, '2026-05-17 16:45:00', '2026-05-18 20:30:00'),
(1810000000000000009, '我把代码评审做成了团队清单，一年后的复盘', '去年中接下团队技术委员会的活儿，第一件事就是治理代码评审：要么没人看，要么全在纠结缩进。\n\n![评审数据看板](http://127.0.0.1:9000/cloudlog/post/content/202606/0454088e-f250-4660-8c96-86ff4c2ccf10.png)\n\n## 三条最有效的改变\n\n1. 风格问题全部交给格式化工具，评审里禁止出现关于空格和换行的意见\n2. 单次评审超过四百行就打回拆分，人的注意力撑不起更大的 diff\n3. 沉淀十二项评审清单，从空指针到日志脱敏，评审前先过一遍机器可查的部分\n\n```text\n[ ] 是否处理了空集合与空对象\n[ ] 异常是否吞掉了堆栈\n[ ] 日志是否包含敏感字段\n[ ] 循环内是否有可外提的查询\n```\n\n一年下来的数据：评审平均停留时长从 26 小时降到 4 小时，上线缺陷里「评审应该拦住」的类别基本清零。清单不是目的，让讨论回到设计本身才是。', '评审流于形式是多数团队的通病。把 checklist 沉淀到模板、把评审范围缩到四百行以内、把风格问题交给工具，一年后团队的首过通过率从三成涨到八成。', 'http://127.0.0.1:9000/cloudlog/post/cover/202606/59e48172-5421-4e36-910d-6b22ad610125.webp', 1800000000000000001, 11, 'published', 1, 1, 850, 2, 0, '2026-06-30 10:00:00', NULL, NULL, '2026-06-29 14:20:00', '2026-06-30 10:00:00'),
(1810000000000000010, 'MySQL 主从延迟排查手记：从 Seconds_Behind 到并行复制', '周三晚上读库延迟告警，监控曲线从 0.5 秒一路爬到 40 秒，评论列表已经读到了十分钟前的数据。这篇手记按当时的排查顺序还原全过程。\n\n![延迟曲线截图](http://127.0.0.1:9000/cloudlog/post/content/202604/573fa79c-c02e-4e85-b938-6a09884d967b.png)\n\n## 先看两个指标\n\nshow slave status 里，Seconds_Behind_Master 只告诉你结果，Slave_SQL_Running_State 才告诉你 SQL 线程此刻在干嘛。当时看到 SQL 线程长期卡在等待依赖事务提交，八九不离十是并行复制被大事务卡住了。\n\n```sql\nSHOW SLAVE STATUS;\n-- 重点看 Seconds_Behind_Master 与 Slave_SQL_Running_State 两列\n```\n\n## 三条根因线\n\n- IO 线程延迟：主库写入量超过网络带宽，监控里的写入量曲线会先于延迟起来\n- 单线程回放：5.7 之前从库回放是单线程，大事务会阻塞后续所有事务\n- 无主键表回放：从库回放 DELETE 走全表扫描，延迟雪上加霜\n\n最终方案：升级 8.0 开默认的 writeset 并行复制，同时把一个凌晨跑的 80 万行更新任务拆成小批。延迟曲线回到 1 秒内，第二天补了对读库延迟的分级告警。', '大促预热期间读库延迟飙到四十秒。从 show slave status 的两个关键指标入手，顺着 IO 线程、SQL 线程和大事务三条线排查，最终靠并行复制与业务拆解解决。', 'http://127.0.0.1:9000/cloudlog/post/cover/202604/a3f80d26-7453-4580-8da0-714eccc2e5a6.webp', 1800000000000000001, 3, 'published', 0, 0, 940, 3, 2, '2026-04-06 09:30:00', NULL, NULL, '2026-04-05 22:10:00', '2026-04-06 09:30:00'),
(1810000000000000011, 'Vite 迁移手记：把老 Vue 项目的构建从 90 秒压到 9 秒', '团队抱怨构建慢已经两年，真正动手只花了一个周五。记录下从 webpack 4 到 Vite 5 的完整迁移过程。\n\n![构建耗时对比](http://127.0.0.1:9000/cloudlog/post/content/202604/fe5c93fc-8193-474c-8e6f-78b8d1f91ff9.png)\n\n## 迁移主线\n\n- 入口与别名配置迁移，define 语义从字符串替换变成真正的常量注入\n- loader 全部退场，样式与资源处理改由 Vite 内建与插件承担\n- CommonJS 依赖放进 optimizeDeps 预打包，个别老库需要 esbuild 配置兜底\n- Jest 换 Vitest，测试文件基本零改动\n\n```ts\n// vite.config.ts\nexport default defineConfig({\n  plugins: [vue()],\n  resolve: { alias: { \"@\": \"/src\" } },\n  server: { proxy: { \"/api\": \"http://127.0.0.1:8080\" } },\n});\n```\n\n## 两个印象最深的坑\n\n环境变量从 webpack 的全网可见变成了 VITE_ 前缀白名单，有三个偷偷埋在业务代码里的配置因此浮出水面。另一个是 HTML 里内联的模板脚本，esbuild 的严格模式让它直接报错，反而揪出了一个潜伏两年的隐患。\n\n![迁移完成日打卡](http://127.0.0.1:9000/cloudlog/post/content/202604/423d5139-d5cc-43e8-91bc-455f70fe3a57.png)\n\n收益：冷启动 9 秒，热更新进入毫秒时代，开发体验的改善立竿见影。', 'webpack 冷构建 90 秒、热更新 8 秒的日子终于结束了。迁移 Vite 的实际工作量比想象中小，但 plugin 兼容与环境变量的坑值得一篇记录。', 'http://127.0.0.1:9000/cloudlog/post/cover/202604/572516ac-dcc1-4253-a115-fb7513491b52.webp', 1800000000000000003, 2, 'published', 0, 0, 610, 2, 1, '2026-04-19 20:15:00', NULL, NULL, '2026-04-18 15:00:00', '2026-04-19 20:15:00'),
(1810000000000000012, 'Redis 集群迁移实录：MOVED、ASK 重定向与灰度切换', '文章收藏功能上线后单实例内存冲到 38GB，决定迁 Cluster。整个过程四天，实际踩的坑比文档里多得多。\n\n![集群拓扑规划图](http://127.0.0.1:9000/cloudlog/post/content/202605/dee079a4-84be-4792-b828-8e8cc1dd7c47.png)\n\n## 迁移前的三件事\n\n- 槽位规划：16384 个槽按业务前缀分片，把热 key 密集的业务固定在独立节点段\n- 客户端验证：旧驱动不支持重定向，先升级到 Lettuce 新版本\n- 容量评估：按当前 1.6 倍冗余规划节点，给未来一年的增长留余地\n\n## 双写灰度与重定向\n\n灰度期间最常出现的是 MOVED 与 ASK 两种重定向，前者表示槽已易主，后者是迁移中的临时状态，客户端必须区分处理：\n\n```redis\nCLUSTER KEYSLOT post:1001:favs\nCLUSTER NODES\n```\n\n![迁移进度时间线](http://127.0.0.1:9000/cloudlog/post/content/202605/cd0d48f4-2121-4133-a8fa-a9012b91e374.png)\n\n数据校验用的是抽样比对加 TTL 巡检，还真抓到一个 bug：迁移工具不搬过期时间，所有 key 在新集群里变成永生。补上 TTL 后才敢全量切流。经验一句话：迁移方案再漂亮，没有校验环节就不算完工。', '从主从架构迁到 Cluster 不是改个连接串就完事。本篇记录槽位规划、双写灰度、重定向处理的完整过程，以及数据校验环节发现的那个隐蔽 bug。', 'http://127.0.0.1:9000/cloudlog/post/cover/202605/611997e6-dd6f-4a13-8cb7-9a7869ec4dba.webp', 1800000000000000001, 4, 'published', 0, 0, 1160, 4, 2, '2026-05-06 10:00:00', NULL, NULL, '2026-05-05 12:30:00', '2026-05-06 10:00:00'),
(1810000000000000013, 'Docker Compose 一套配置跑齐 MySQL、Redis 与 MinIO', '每来一个新同事，环境搭建都要折腾一两天。后来把整套依赖写进一份 Compose 文件，现在是一条命令十分钟跑通。\n\n![本地环境编排结构](http://127.0.0.1:9000/cloudlog/post/content/202605/6d018121-551c-4405-a3b8-5951ac8c6505.png)\n\n## 编排里的三个关键细节\n\n1. 健康检查必须配，depends_on 只保证启动顺序，不保证服务就绪，没有 healthcheck 应用会连接失败重启循环\n2. 数据卷要显式命名，匿名卷在重建容器时容易被静默清掉，第一次丢数据后就再也不敢省这一行\n3. 初始化脚本挂到 docker-entrypoint-initdb.d，只在数据目录为空时执行一次，建表 SQL 从仓库读取而不是拷贝进镜像\n\n```yaml\nservices:\n  mysql:\n    image: mysql:8.4\n    healthcheck:\n      test: [\"CMD\", \"mysqladmin\", \"ping\", \"-h\", \"127.0.0.1\"]\n      interval: 10s\n      retries: 12\n```\n\n![一键启动效果](http://127.0.0.1:9000/cloudlog/post/content/202605/084c443f-a6c1-4aae-ae69-37ad80ddc937.png)\n\n另外两个小经验：端口尽量不发布到宿主机，需要调试时用临时配置；密码一律走 .env 文件，编排文件里不出现任何真实凭据。这套编排半年没改过，稳定得让人安心。', '新人入职环境搭建从两天缩短到一条命令。分享一份自用的 Compose 编排，重点讲健康检查、数据卷与初始化脚本这三处容易翻车的细节。', 'http://127.0.0.1:9000/cloudlog/post/cover/202605/fe0781c1-a7fa-4646-ae0e-aed2ac456771.webp', 1800000000000000002, 5, 'published', 0, 0, 470, 1, 1, '2026-05-25 16:45:00', NULL, NULL, '2026-05-24 11:20:00', '2026-05-25 16:45:00'),
(1810000000000000014, 'Spring Security 登录风控实战：失败锁定、验证码与 IP 黑名单', '上个月的登录日志里出现了明显的撞库痕迹：同一个 IP 对三百个邮箱轮询尝试。虽然没有任何一次成功，但足以把登录风控提到最高优先级。\n\n![攻击日志分析](http://127.0.0.1:9000/cloudlog/post/content/202606/e62b9921-f63e-4908-8c9d-30c289eb3390.png)\n\n## 三道闸门\n\n1. 失败锁定：同一账号连续失败五次锁定十五分钟，锁定期间的尝试不再校验口令，连「邮箱是否存在」的侧信道也一并关掉\n2. 动态验证码：失败两次后升级出验证码，正常用户几乎无感，脚本成本陡增\n3. IP 信誉：失败率异常的 IP 直接进冷却名单，配合 Nginx 层限流双保险\n\n```java\nif (failures >= MAX_FAILURES && lockedUntil.isAfter(now)) {\n    throw new LockedException(\"account locked\");\n}\n```\n\n## 设计上的两个取舍\n\n锁定状态不回显给前端具体原因，统一返回凭证错误，避免帮攻击者确认哪些账号存在。解锁时间用指数退避而不是固定值，让自动化工具的成本进一步变高。\n\n![风控闸门分层图](http://127.0.0.1:9000/cloudlog/post/content/202606/15efdab2-6407-401c-9dcb-4743f27fc62f.png)\n\n安全没有一劳永逸，日志要常看。现在团队养成了每周翻一遍登录日志的习惯，风控规则也跟着真实攻击形态迭代。', '撞库攻击提醒我们登录接口必须设防。用失败计数锁定、动态验证码升级与 IP 信誉三级闸门，把暴力破解的成功率压到接近零，附完整配置思路。', 'http://127.0.0.1:9000/cloudlog/post/cover/202606/bbdeced2-3f24-4d43-b553-5ec55ab55b7a.webp', 1800000000000000013, 10, 'published', 0, 0, 520, 2, 1, '2026-06-08 11:20:00', NULL, NULL, '2026-06-07 20:40:00', '2026-06-08 11:20:00'),
(1810000000000000015, 'Kafka 消息不丢的三道防线：从生产者到消费端的幂等闭环', '统计接口偶现对不上账，排查一周后定位到一条消息在 Broker 迁移时丢失。复盘时把整条链路的防丢配置重新过了一遍。\n\n![消息链路三道防线](http://127.0.0.1:9000/cloudlog/post/content/202606/d1cc1615-03dd-4a6c-a00a-f9ba816412a7.png)\n\n## 第一道：生产者确认\n\nacks=all 配合 retries 与幂等生产者，消息在发送侧就有副本保障。吞吐会掉一截，但账务类 topic 值得：\n\n```properties\nacks=all\nenable.idempotence=true\nretries=2147483647\n```\n\n## 第二道：Broker 副本\n\nmin.insync.replicas 至少为 2，配合三副本，允许一台 Broker 退出而不丢数据。跨机架部署这个前提别忽略，两副本放同一机架等于没做。\n\n## 第三道：消费端位移\n\n先处理后提交位移，代价是可能重复消费，所以消费逻辑必须幂等。我们的做法是业务去重表加状态机，重复消息进来直接短路。\n\n![消费幂等时序图](http://127.0.0.1:9000/cloudlog/post/content/202606/2f3f643c-e25a-45df-ad9e-96be69d9ccec.png)\n\n丢消息的完整闭环是：发送端确认、存储端冗余、消费端幂等，缺任何一环都会在某个深夜给你惊喜。事后我们把三道防线的配置做成了上线检查单。', '消息丢失从来不是单点问题。acks 配置、副本同步与消费位移提交，三道防线各管一段，本文用一次真实的丢消息事故串起完整链路的配置要点。', 'http://127.0.0.1:9000/cloudlog/post/cover/202606/fe516152-0049-4e31-a789-69638d1c76dd.webp', 1800000000000000001, 15, 'published', 0, 0, 690, 2, 2, '2026-06-21 15:30:00', NULL, NULL, '2026-06-20 10:15:00', '2026-06-21 15:30:00'),
(1810000000000000016, '把大模型接进内部知识库：RAG 检索质量调优的八次迭代', '给内部文档站加问答功能，第一版的回答质量差到没人愿意用。于是开始了长达六周的检索调优马拉松。\n\n![迭代命中率曲线](http://127.0.0.1:9000/cloudlog/post/content/202607/1deb9f1c-0f3c-4948-bfa0-bbb44296bbc1.png)\n\n## 八轮迭代压缩版\n\n1. 固定 512 字分块改成按标题层级分块，命中率从 41 到 53\n2. 向量检索叠加 BM25 混合召回，专业术语类的漏召回明显减少\n3. 加 cross-encoder 重排，top5 相关性显著改善\n4. 查询改写：把口语化问题先改写成检索友好形式\n5. 元数据过滤：按文档类型与更新时间先砍掉一半候选\n6. 去重与父子块策略，避免同一段落重复占坑\n7. 召回数量与上下文窗口的平衡实验，多不等于好\n8. 评测集驱动：50 个真实问题建立回归基线，每轮改动看数据说话\n\n```python\nhits = hybrid_search(query, dense_k=20, sparse_k=20)\ntop = reranker.rerank(query, hits)[:5]\n```\n\n![评测集回归结果](http://127.0.0.1:9000/cloudlog/post/content/202607/3101a462-628b-4b7c-ab1b-a02d399af4c3.png)\n\n最大的一条经验：先建评测集再调优，否则每一轮改动都是在凭感觉开药方。模型侧的提示词调整收益反而最小，检索质量才是 RAG 的天花板。', '直接套开源 RAG 模板的检索准确率惨不忍睹。从分块策略到混合检索再到重排，八轮迭代把命中率从 41% 提到 86%，每轮改动与收益都有数据支撑。', 'http://127.0.0.1:9000/cloudlog/post/cover/202607/4e1d34a4-2de6-4bd2-b4d8-ad20faa116e4.webp', 1800000000000000016, 13, 'published', 0, 0, 830, 3, 1, '2026-07-12 09:10:00', NULL, NULL, '2026-07-11 09:50:00', '2026-07-12 09:10:00'),
(1810000000000000017, '移动端 H5 首屏优化实录：从 4.8 秒到 1.2 秒', '市场部反馈活动页转化率异常，抓了一台千元机实测，首屏 4.8 秒，用户早就划走了。\n\n![首屏瀑布图](http://127.0.0.1:9000/cloudlog/post/content/202608/3b0472e3-7a3f-44cc-99ef-c23b126a2ca8.png)\n\n## 六个改动\n\n1. 首屏图片全部换成 WebP 并按视口尺寸出图，图片传输量降七成\n2. 关键 CSS 内联，其余样式异步加载，渲染阻塞清零\n3. JS 按路由分包，首屏只加载活动逻辑本身\n4. 字体子集化，全量字体包从 1.8MB 压到 96KB\n5. 接口预取：HTML 到达前用 prefetch 提前拉首屏数据\n6. 骨架屏兜底，感知性能与实际性能一起管\n\n```html\n<link rel=\"prefetch\" href=\"/api/activity/summary\" />\n```\n\n## 实测数据\n\n千元机上首屏 4.8 秒到 1.2 秒，iOS 中端机 1.9 秒到 0.7 秒。转化率回升了 18 个百分点，这可能是今年性价比最高的一周。\n\n![优化前后对比](http://127.0.0.1:9000/cloudlog/post/content/202608/61e0d313-793a-401a-b893-0740ab9ab598.png)\n\n移动端优化的方法论不新鲜，难的是把每一项落到真实机型上验证。模拟器给出的数据永远偏乐观。', '活动页在低端安卓机上首屏要 4.8 秒，流失率触目惊心。从资源、渲染到缓存六个改动做完，首屏压到 1.2 秒，每一步都有真实机型测试数据。', 'http://127.0.0.1:9000/cloudlog/post/cover/202608/144b064f-c880-43e9-a643-d8920afa1511.webp', 1800000000000000012, 14, 'published', 0, 0, 360, 1, 0, '2026-08-02 22:00:00', NULL, NULL, '2026-08-01 21:30:00', '2026-08-02 22:00:00'),
(1810000000000000018, '单体到微服务的第 700 天：后悔的三件事与庆幸的两件事', '拆分第 700 天，恰好赶上半年复盘。不写方法论，只写真实体感。\n\n![服务拆分全景图](http://127.0.0.1:9000/cloudlog/post/content/202608/dfe89859-a665-413e-b395-d8a5bcd8995f.png)\n\n## 后悔的三件事\n\n1. 拆得太早：领域边界没想清楚就动手，两个服务之间的调用关系三个月里重构了四次\n2. 共享库泛滥：本想统一基础设施，结果一个工具类的升级要八个服务协同发版，比单体还累\n3. 分布式事务想简单了：最终一致性方案的补偿逻辑，代码量是当初预估的三倍\n\n## 庆幸的两件事\n\n1. 链路追踪第一天就上线：没有它，线上问题定位时长会至少翻倍\n2. 网关层统一了认证与限流：各服务省下的重复建设远超投入\n\n![调用链追踪示例](http://127.0.0.1:9000/cloudlog/post/content/202608/9fb8307c-8c18-4328-9cbd-e74af2f31e9d.png)\n\n如果要给一个数字结论：只有当团队超过三个、且各域发布节奏互相拖累时，拆分才开始划算。我们拆对了边界，但低估了协同成本，这是混合评价的原因。', '拆微服务一年半，有些决策被时间证明是对的，有些则每天都在还债。不谈方法论，只讲三个后悔与两个庆幸，给正准备拆分的团队一点真实样本。', 'http://127.0.0.1:9000/cloudlog/post/cover/202608/dc253f6b-cae5-497d-99b1-0d208e6a01dc.webp', 1800000000000000010, 19, 'published', 0, 0, 450, 1, 1, '2026-08-24 19:35:00', NULL, NULL, '2026-08-23 17:10:00', '2026-08-24 19:35:00'),
(1810000000000000019, '写技术博客一百篇之后：输出如何反过来重塑输入', '上周日晚上发了第一百篇博客。没有爆款，涨粉缓慢，但这项习惯值得为它写一篇总结。\n\n![一百篇的存稿箱](http://127.0.0.1:9000/cloudlog/post/content/202609/0dbb6ccb-82e7-428a-9a28-96f395c03561.png)\n\n## 写作带来的三个变化\n\n1. 学习方式变了：以前看懂就过，现在会先问自己能不能把这段讲给别人听\n2. 知识开始复利：半年前写的部署笔记，成了今天排障时自己的速查手册\n3. 社交半径扩大：通过评论认识了几位同行，讨论质量远高于群聊\n\n## 一些诚实的代价\n\n每篇平均要花四到六个小时，周末的整块时间基本交了出去。有三个月陷入数据焦虑，文章开始迎合关键词，后来主动停更一个月才调整回来。\n\n![写作时间统计](http://127.0.0.1:9000/cloudlog/post/content/202609/0d0edc07-47c6-47ad-a918-7f09c4066695.png)\n\n给想开始的人一个建议：降低单篇的完成标准，提高更新的连续性。写作是对思考的训练，不是表演。', '坚持写博客两年整，累计一百篇。写作没有直接带来 offer 或流量，但它强迫我把模糊的理解掰开揉碎，这种反哺比任何学习方法都扎实。', 'http://127.0.0.1:9000/cloudlog/post/cover/202609/788c1c24-6e8a-47af-bc70-d3f60d358f54.webp', 1800000000000000015, NULL, 'published', 0, 0, 290, 1, 0, '2026-09-05 08:05:00', NULL, NULL, '2026-09-04 22:40:00', '2026-09-05 08:05:00'),
(1810000000000000020, '聊聊那次开源许可证风波：我们到底在焦虑什么', '六月那场许可证变更风波波及了我们两个核心依赖，作为踩在前线的人，记录下当时的评估过程与结论。\n\n![事件时间线整理](http://127.0.0.1:9000/cloudlog/post/content/202606/d2332eb7-6b7a-4128-87f1-c63fe052fb69.png)\n\n## 事件时间线与影响面\n\n梳理许可证条款的三处关键变更，以及对我们商用场景的实际影响：孵化条款、网络服务条款与专利授予范围，逐一对照法务意见。\n\n## 技术上的应对\n\n- 盘点直接与传递依赖，标注每一处的许可证类型\n- 评估替代方案的成本，从迁移工作量到生态成熟度\n- 准备双方案：锁版本短期续命，抽象层长期留后门\n\n![依赖许可证盘点表](http://127.0.0.1:9000/cloudlog/post/content/202606/e32a3434-d1dd-472c-90f9-e4723466c6bd.png)\n\n本文涉及尚未公开的合作细节，经与管理层沟通暂时下线，结论部分会以脱敏版另发。', '一次许可证变更引发的社区震动，波及我们正在使用的核心依赖。文章记录了当时的技术评估与应对，因涉及具体项目的未公开细节，应编辑要求暂时下线。', 'http://127.0.0.1:9000/cloudlog/post/cover/202606/47308d60-a1c7-4922-b993-4f456826dee0.webp', 1800000000000000002, 11, 'offline', 0, 0, 1320, 0, 0, '2026-06-12 13:20:00', 1800000000000000001, '2026-09-12 10:05:00', '2026-06-11 15:25:00', '2026-09-12 10:05:00'),
(1810000000000000021, '一次失败的重构复盘：我把发布时间拖长了三倍', '这是一篇自我打脸的文章。半年前主导的重构没有带来预期收益，反而拖累了整个团队的发布节奏，原文保留不删，作为长期警示。\n\n![发布耗时变化](http://127.0.0.1:9000/cloudlog/post/content/202605/331ff51c-c604-4949-b1c2-0f9acdae2ef6.png)\n\n## 当时的判断错在哪\n\n- 只数了重复代码的行数，没数变更频率：低频重复根本不值得抽象\n- 过早引入间接层，调用链从一层变成四层，排查成本指数上升\n- 没有设定退出条件，重构变成沉没成本的绑架\n\n## 现在的判断标准\n\n重构开工前先回答三个问题：这个重复过去一年变过几次？抽象后的调用链会增加几层？两周内能不能灰度回滚？答不上来就不动。\n\n![重构前后调用链](http://127.0.0.1:9000/cloudlog/post/content/202605/05803a65-86ce-4cf9-92f4-11c5a41581ba.png)\n\n下线原因：结论已被后来几篇笔记覆盖，且示例代码有误导性。留着原文不如留着教训，这句写在开头的话就是全部遗产。', '半年前主导的一次抽象层重构，初衷是消除重复代码，结果把原本十分钟的发布流程拖成了半小时。文章保留作自我警示：没有量化收益的重构不该开工。', 'http://127.0.0.1:9000/cloudlog/post/cover/202605/8a8ac972-35ac-4548-901f-ccbccd17c90f.webp', 1800000000000000001, 19, 'offline', 0, 0, 780, 0, 0, '2026-05-20 09:15:00', 1800000000000000001, '2026-08-15 21:40:00', '2026-05-19 18:05:00', '2026-08-15 21:40:00'),
(1810000000000000022, 'MySQL 8.4 升级前置清单：参数变更、废弃语法与回滚预案', '生产库升级 8.4 LTS 定在下周三凌晨，这篇清单是升级方案的最后一稿，发布后会把实测结果补进来。\n\n![升级窗口排期](http://127.0.0.1:9000/cloudlog/post/content/202610/573edd7d-1141-4574-8c02-9cb5413fa7c6.png)\n\n## 参数与默认值变化\n\n- 默认认证插件与字符集在 8.0 已切换，8.4 重点是删除了对旧认证方式的支持\n- 部分性能参数的默认值调整，会直接影响现有慢查询基线\n- 组复制相关参数合并，主从架构需要重新核对配置模板\n\n## 废弃语法排查\n\n应用侧用检索工具扫了一遍 SQL 模板，确认没有依赖已移除的特性；存储过程里有两处写法需要改写，已列入变更单。\n\n```sql\nSELECT VERSION();\nSHOW WARNINGS;\n```\n\n## 回滚预案\n\n- 升级前全量备份加 binlog 位点记录\n- 主从先升从库，验证读流量两小时再切主\n- 回滚按「新库降级不可行」假设设计，只能走备份重建\n\n![备份演练记录](http://127.0.0.1:9000/cloudlog/post/content/202610/89aa5640-eb52-4bf8-8a44-90ac8f4aaeef.png)\n\n升级窗口四小时，实际操作预留一小时，剩余时间全部留给观察与验证。', '下周三凌晨把生产库从 8.0 升到 8.4 LTS。清单里整理了参数默认值变化、移除的语法特性与分阶段回滚预案，发布后补充实测记录。', 'http://127.0.0.1:9000/cloudlog/post/cover/202610/36635dd9-eac7-4852-b32f-1f520a39a4da.webp', 1800000000000000001, 3, 'scheduled', 0, 0, 0, 0, 0, '2026-10-15 09:30:00', NULL, NULL, '2026-10-03 11:30:00', '2026-10-03 11:30:00'),
(1810000000000000023, 'macOS 上用 Colima 跑容器的完整配置笔记', 'Docker Desktop 的订阅条款变更之后，把开发机迁到了 Colima。试用两周，这篇笔记是最终的配置定型稿，下周会补上团队推广的结果。\n\n![Colima 资源占用](http://127.0.0.1:9000/cloudlog/post/content/202610/8c8f1c33-eac8-45e8-95bb-7a2b368dd763.png)\n\n## 为什么选 Colima\n\n- 免费且无商业条款争议，社区活跃度足够\n- lima 虚拟机层的资源开销比 Desktop 低，风扇终于安静了\n- docker CLI 与 compose 完全兼容，团队脚本零改动\n\n```bash\ncolima start --cpu 4 --memory 8 --disk 60\ndocker context use colima\n```\n\n## 三个踩过的坑\n\n1. 卷挂载性能依赖 virtiofs，旧版本默认 9p，编译类项目会慢到怀疑人生\n2. 端口转发需要显式放行段，Host 头校验的服务要加额外参数\n3. k3d 与 Colima 的网络配置有冲突，顺序启动可以规避\n\n![配置定型稿截图](http://127.0.0.1:9000/cloudlog/post/content/202610/35655187-5543-4e96-bddb-763e214d4bd2.png)\n\n如果新方案下周跑顺，会把这篇升级成团队 wiki 的正式配置，附带一键初始化脚本。', 'Docker Desktop 的订阅条款劝退之后，试了三条替代路线。最终落在 Colima：资源占用更少，命令行完全兼容，本文是踩完坑后的配置定型稿。', 'http://127.0.0.1:9000/cloudlog/post/cover/202610/4940dfc2-a7e3-4453-b6f5-03a7e94c2842.webp', 1800000000000000002, 5, 'scheduled', 0, 0, 0, 0, 0, '2026-10-28 20:00:00', NULL, NULL, '2026-10-04 08:40:00', '2026-10-04 08:40:00'),
(1810000000000000024, 'Redis 6 多线程网络 IO 的源码导读笔记', '读源码的第 12 天，网络 IO 多线程这部分的主干终于理顺了，先把笔记主体存进草稿，读完执行模型再补完。\n\n![源码阅读笔记](http://127.0.0.1:9000/cloudlog/post/content/202610/aeb5c0b0-e25d-4560-afae-9049999012a2.png)\n\n## 已确认的三件事\n\n1. 主线程负责事件分发与命令执行，IO 线程只做读写与协议解析，命令执行仍是单线程\n2. IO 线程数设为机器核数减一以内才有收益，盲目拉满反而抖动\n3. 客户端输出缓冲区回写是分批的，大批量响应的调度策略值得单独写\n\n```c\n// iothreads 的核心循环：自旋等待其他 IO 线程同步\nwhile (1) {\n    /* 忙轮询同步点 */\n}\n```\n\n## 待补内容\n\n执行模型里对 pipeline 与事务的处理还没读完，另外想补一个多线程开关前后基准测试的对照实验。', '正在逐段读 Redis 6 网络线程池的实现，IO 线程的分工、任务队列与回写时机已经理清，执行模型部分还没读完，先存草稿。', 'http://127.0.0.1:9000/cloudlog/post/cover/202610/427b81c6-4e9e-4a93-8d7c-476e2ec06deb.webp', 1800000000000000001, 4, 'draft', 0, 0, 0, 0, 0, NULL, NULL, NULL, '2026-10-01 16:20:00', '2026-10-01 16:20:00'),
(1810000000000000025, 'Vue 列表性能优化清单：从 keep-alive 到虚拟滚动', '中后台的列表页性能问题又双叒叕来了，索性把过去三年攒的优化手段整理成清单，写完一半先存着。\n\n![虚拟滚动帧率对比](http://127.0.0.1:9000/cloudlog/post/content/202610/461ca071-addc-441e-92c4-507e18144ea9.png)\n\n## 已写完的部分\n\n1. 虚拟滚动：万行列表的渲染时间对比，滚动帧率从 12 到 58\n2. 分页缓存：翻页回退不重新请求的缓存键设计\n3. 懒加载与 IntersectionObserver 的正确用法\n\n## 待完成的实验\n\nkeep-alive 在路由切换时的失效场景，特别是 include 配合动态组件的行为，实验做了一半，结论还不稳。\n\n```js\nconst { items, containerProps, wrapperProps } = useVirtualList(data, { itemHeight: 48 });\n```\n\n预计下周补完发布，评论区如果有踩过 keep-alive 坑的同学，欢迎先留言交流。', '整理中的一份长列表优化清单，虚拟滚动与分页缓存的骨架已经写完，keep-alive 的失效场景实验还没做完，预计下周发布。', 'http://127.0.0.1:9000/cloudlog/post/cover/202610/fd22dfc9-952b-4367-af5e-f7db115cbda2.webp', 1800000000000000003, 2, 'draft', 0, 0, 0, 0, 0, NULL, NULL, NULL, '2026-10-02 14:35:00', '2026-10-02 14:35:00'),
(1810000000000000026, 'MySQL 死锁日志分析入门：一次真实死锁现场的全过程拆解', '上个月处理了一次教科书级的死锁，日志留存得很完整，适合拆开讲给新同事。初稿先记录时序还原部分。\n\n![死锁时序还原草图](http://127.0.0.1:9000/cloudlog/post/content/202610/3ca2b6b0-c475-42fa-9e9d-5ed230fa4b9c.png)\n\n## 现场还原\n\n两个事务以相反顺序更新同一组行，间隙锁又恰好交叉，最终形成环路。show engine innodb status 的日志里，两种锁的持有与等待关系要对照表索引逐行读。\n\n```sql\nSHOW ENGINE INNODB STATUS;\n-- LATEST DETECTED DEADLOCK 段落是主战场\n```\n\n## 拆解计划\n\n正文计划分三节：锁的时序图、为什么间隙锁会交叉、以及统一加锁顺序的改法。时序图还没画完，先占坑。\n\n![间隙锁交叉示意](http://127.0.0.1:9000/cloudlog/post/content/202610/e2f31b0f-4078-487c-839d-7f0b68c51d3a.png)\n\n定稿时会把表结构脱敏成订单模型，方便对号入座。', '把上个月一次线上死锁的日志与表结构脱敏后作为教学案例，从两阶段加锁的时序图讲起，初稿写到一半，配上时序图后发布。', 'http://127.0.0.1:9000/cloudlog/post/cover/202610/fa536991-17b1-4f27-9e01-3ebdad0020bd.webp', 1800000000000000002, 3, 'draft', 0, 0, 0, 0, 0, NULL, NULL, NULL, '2026-09-30 10:12:00', '2026-09-30 10:12:00');
