INSERT INTO `comments` (`id`, `post_id`, `user_id`, `content`, `parent_id`, `status`, `hit_word`, `created_at`) VALUES
(1, 1810000000000000001, 1800000000000000003, '这篇来得太及时，我们上个月也被 JDK 序列化的体积坑过，缓存一上内存告警就来了。请问 Jackson 配置你们是全局统一还是按缓存分区做的？', 0, 'approved', NULL, '2026-10-02 11:05:00'),
(2, 1810000000000000001, 1800000000000000007, '内部调用绕过代理这个坑我也踩过，当时调试了一下午才反应过来是 AOP 的问题。拆类确实是比自注入更体面的解法。', 0, 'approved', NULL, '2026-10-02 14:22:00'),
(3, 1810000000000000001, 1800000000000000008, '我们是按分区做的，列表和详情的序列化配置不一样，详情里的时间字段要保时区。', 1, 'approved', NULL, '2026-10-02 16:40:00'),
(4, 1810000000000000001, 1800000000000000011, 'TTL 加随机抖动确实立竿见影，我们加上之后 DB 的 QPS 曲线从锯齿变成了平线，建议直接写进团队规范。', 0, 'approved', NULL, '2026-10-03 09:12:00'),
(5, 1810000000000000001, 1800000000000000002, '补充一个细节，抖动幅度别超过基础 TTL 的一成，不然监控里的命中率会变得很难读。', 4, 'approved', NULL, '2026-10-03 10:30:00'),
(6, 1810000000000000001, NULL, '搜序列化体积爆炸找到这里，收益了，博客样式也好看，收藏了。', 0, 'approved', NULL, '2026-10-03 21:18:00'),
(7, 1810000000000000002, 1800000000000000004, '第一个隐式转换的案例就是我们线上真实发生过的，压测三天没问题，上了生产第三天就告警，类型一致这条现在写进了我们的评审清单。', 0, 'approved', NULL, '2026-10-02 08:40:00'),
(8, 1810000000000000002, 1800000000000000006, '测试侧补一句，这类问题在预发根本暴露不出来，数据量不到量级执行计划就是不会切。', 7, 'approved', NULL, '2026-10-02 09:55:00'),
(9, 1810000000000000002, 1800000000000000010, '建议补一个案例：联合索引里对第二列做范围查询导致第三列失效，这个在我们的订单表上翻过车。', 0, 'approved', NULL, '2026-10-02 20:31:00'),
(10, 1810000000000000002, 1800000000000000014, '收藏了，回头拿这十个案例给组里新人做一轮评审训练，比讲 PPT 有用。', 0, 'approved', NULL, '2026-10-03 12:04:00'),
(11, 1810000000000000002, 1800000000000000004, '同款经历，后来我们把范围列统一放到联合索引末尾，配合覆盖索引才算消停。', 9, 'approved', NULL, '2026-10-03 13:26:00'),
(12, 1810000000000000003, 1800000000000000021, '不是后端也被科普明白了，原来锁还有这么多讲究，感谢写这么细。', 0, 'approved', NULL, '2026-09-28 10:05:00'),
(13, 1810000000000000003, 1800000000000000019, '想请教下看门狗续期的线程池参数你们调过吗，默认值在高峰期似乎有点保守。', 0, 'approved', NULL, '2026-09-29 19:22:00'),
(14, 1810000000000000003, 1800000000000000001, '能帮到非后端同学就值了，锁这东西原理不难，难的是把每个边界情况都想周全。', 12, 'approved', NULL, '2026-09-30 08:47:00'),
(15, 1810000000000000003, NULL, '用 DuckDB 的路过，表示分布式锁这门课迟早要补，先马后看。', 0, 'approved', NULL, '2026-09-30 22:41:00'),
(16, 1810000000000000004, 1800000000000000011, '迁移节奏那段说得太对了，我们当时立了三个月全迁的军令状，后半程全是硬着头皮在还债。', 0, 'approved', NULL, '2026-07-05 10:12:00'),
(17, 1810000000000000005, 1800000000000000009, '不懂技术但是看完了，原来镜像还有这么大的压缩空间，以后可以催着研发部把发布搞快点。', 0, 'approved', NULL, '2026-09-15 10:31:00'),
(18, 1810000000000000005, 1800000000000000002, '产品同学能看完这篇已经是真爱了，发布提速这事回头请你们喝奶茶。', 17, 'approved', NULL, '2026-09-15 21:08:00'),
(19, 1810000000000000006, 1800000000000000012, '五种方案的对比太实用了，我们目前还在数据库轮询阶段，日订单马上破十万，看来得计划升级了。', 0, 'approved', NULL, '2026-09-20 15:44:00'),
(20, 1810000000000000006, 1800000000000000017, '时间轮那部分深有同感，进程一重启任务就丢，最后还是加了持久化，等于自己实现了一遍延迟消息。', 0, 'approved', NULL, '2026-09-21 09:26:00'),
(21, 1810000000000000006, 1800000000000000010, '十万日单量建议直接上 RocketMQ 延迟消息，轮询的扫表压力会先于你们的技术债爆发。', 19, 'approved', NULL, '2026-09-21 14:53:00'),
(22, 1810000000000000007, 1800000000000000015, '清单式的写法太友好了，已经把状态机那条转给了订单组的同学，条件更新确实是最容易被低估的幂等方案。', 0, 'approved', NULL, '2026-05-02 11:18:00'),
(23, 1810000000000000008, 1800000000000000006, '游标翻页我们去年也上了，唯一难受的是产品坚持要跳页，最后做了个混合方案，页码浅走 offset 深走游标。', 0, 'approved', NULL, '2026-05-19 09:40:00'),
(24, 1810000000000000010, 1800000000000000008, '正在准备面试，这篇排查思路的顺序感太强了，先看状态再看线程再看大事务，记下了。', 0, 'approved', NULL, '2026-04-07 20:26:00'),
(25, 1810000000000000010, 1800000000000000001, '面试时能讲出排查顺序和依据，比背八股有说服力得多，祝顺利。', 24, 'approved', NULL, '2026-04-08 08:55:00'),
(26, 1810000000000000011, 1800000000000000009, '90 秒到 9 秒这个数字看得我眼馋，已经转给前端负责人了，期待下周的构建时间周报。', 0, 'approved', NULL, '2026-04-20 13:34:00'),
(27, 1810000000000000012, 1800000000000000007, '不搬过期时间这个 bug 太真实了，我们迁移时也中过招，之后把 TTL 巡检写成了固定验收项。', 0, 'approved', NULL, '2026-05-07 10:02:00'),
(28, 1810000000000000012, 1800000000000000014, '同中过招，而且是在灰度切了一半之后发现的，好在回滚及时，现在想起还是后背发凉。', 27, 'approved', NULL, '2026-05-07 18:36:00'),
(29, 1810000000000000013, 1800000000000000018, '匿名卷丢数据那个我替大家谢谢作者，第一次丢数据那天我们的表情现在还留在部门表情包里。', 0, 'approved', NULL, '2026-05-26 12:15:00'),
(30, 1810000000000000014, 1800000000000000013, '补充一点，锁定期间不回显具体原因这条特别重要，我们审计时发现有的站点连账号存在性都能探测，这种侧信道很多团队都忽略了。', 0, 'approved', NULL, '2026-06-09 09:21:00'),
(31, 1810000000000000015, 1800000000000000016, '三道防线的总结很清晰，我们踩过 min.insync.replicas 配成 1 的坑，一次 Broker 滚动重启就丢了半分钟数据。', 0, 'approved', NULL, '2026-06-22 17:45:00'),
(32, 1810000000000000015, 1800000000000000001, '配成 1 等于把第二道防线拆了，账务 topic 上这个配置该直接拦在上线检查单里。', 31, 'approved', NULL, '2026-06-23 08:33:00'),
(33, 1810000000000000016, 1800000000000000003, '先建评测集这条对所有调优场景都成立，我们做性能优化也是同理，没有基线的优化全是玄学。', 0, 'approved', NULL, '2026-07-13 10:29:00'),
(34, 1810000000000000018, 1800000000000000020, '拆得太早这条扎心了，我们是两个人四个服务，链路追踪是唯一支撑我们没散架的东西。', 0, 'approved', NULL, '2026-08-25 20:57:00'),
(35, 1810000000000000001, 1800000000000000018, '站长你好，我们是做 App 推广的，长期承接各类推广业务，也接单做内容合作，价格好谈，方便的话留个联系方式细聊。', 0, 'pending', '接单', '2026-10-03 23:12:00'),
(36, 1810000000000000002, 1800000000000000018, '作者好，我们是做电商服务的，有稳定渠道可以帮商家刷单做销量，也可以合作导流，有意向的话回我一下。', 0, 'pending', '刷单', '2026-10-03 19:40:00'),
(37, 1810000000000000003, 1800000000000000008, '同学求问一个不相关的事，知道哪里能办证吗，急用，有的话私我，谢谢。', 0, 'pending', '办证', '2026-09-29 08:14:00'),
(38, 1810000000000000012, 1800000000000000005, '楼主的方案我照着搭好了，顺便引流一下我自己写的迁移笔记，思路类似，欢迎大家来交流踩坑。', 0, 'pending', '引流', '2026-05-07 23:58:00'),
(39, 1810000000000000006, 1800000000000000014, '写得什么玩意儿，全是网上抄的吧，浪费我十分钟。', 0, 'rejected', NULL, '2026-09-21 18:02:00'),
(40, 1810000000000000010, 1800000000000000018, '需要运维监控模板的可以私我，有偿分享，速度。', 0, 'rejected', NULL, '2026-04-12 19:46:00'),
(41, 1810000000000000001, 1800000000000000017, '呵呵，就这水平也敢发出来？建议全删了重写。', 0, 'rejected', NULL, '2026-10-03 20:15:00');
