(1, 'author@example.com', '$2a$10$tfxOcwDQ9JEjqxRYhnmiMORf04lbADUfr8UWBKMJyrYkECDYSNo/.', 'author', NULL, '测试锚点账号：只为 mapper 层写死的「作者 1」提供属主行，不承担内容。', '后端工程师', 'admin', 1, NULL, NULL, '2025-10-07 08:00:00', '2026-10-04 09:12:00'),
(3, 'alex@example.com', '$2a$10$tfxOcwDQ9JEjqxRYhnmiMORf04lbADUfr8UWBKMJyrYkECDYSNo/.', 'alex', NULL, '测试锚点读者账号：过滤链测试用它签 token，账号必须启用。', NULL, 'user', 1, NULL, NULL, '2025-10-09 16:30:00', '2026-09-28 20:05:00');
INSERT INTO `posts` (`id`, `title`, `content`, `excerpt`, `cover`, `author_id`, `category_id`, `status`, `is_top`, `top_order`, `view_count`, `like_count`, `comment_count`, `published_at`, `offlined_by`, `offlined_at`, `created_at`, `updated_at`) VALUES
(1810000000000000027, '从零把一个小站容器化：编排顺序、健康检查与凭据边界', '把自己的小站塞进 compose 之后才发现，麻烦不在打包，而在**谁等谁**。\n\n## 三条经验\n\n1. 依赖顺序不要写 `depends_on` 了事，要用 `condition: service_healthy`：Spring Boot 一起来就抢连接池，库没就绪就是重启死循环\n2. 凭据不要烤进镜像：`${ENV}` 占位 + 仓库根 `.env`，`.dockerignore` 再挡一道构建上下文\n3. 只发布一个入口端口：后端留在内部网络里，反向代理才能安全地覆盖写 `X-Forwarded-For`\n\n结构性配置（比如 `pagehelper.params` 这类 Map）经环境变量传会绑不进去，得靠挂载同名配置文件补——这部分写在 README 的容器化一节。', '小站容器化的一手经验：编排顺序靠健康检查、凭据只从仓库根 .env 取、结构性配置得靠挂载补。', NULL, 1, 1, 'published', 0, 0, 86, 0, 0, '2026-09-28 10:00:00', NULL, NULL, '2026-09-27 21:40:00', '2026-09-28 10:00:00'),
(1810000000000000028, '待写：读写分离在我这个量级上到底值不值', '草稿。先记两个前提：单库单实例、写 QPS 个位数，读放大主要出在列表页的计数列上。\n\n要验的问题只剩一个——加一层只读副本之后，主库的复制延迟会不会把「刚发布看不到」变成新的坑。', NULL, NULL, 1, 1, 'draft', 0, 0, 0, 0, 0, NULL, NULL, NULL, '2026-10-03 21:05:00', '2026-10-04 09:12:00');
